-- 82 Stained Light: the sun through coloured glass onto the floor, and
-- `global_illumination` bouncing it on to the wall and the pillars. The sun
-- drifts, so the patches walk across the floor and the glow follows them.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/82-stained-light.scene"
local SUN = -0.62
local captions = true
local sun, status
local shafts = {}
local bounce = true
local t = 0

local function show()
    UI.set_text(status, "bounce light " .. (bounce and "on" or "off"))
end

function init(entity)
    sun = Entity.find_by_name("Sun")
    status = Entity.find_by_name("Status")
    for i = 1, 4 do shafts[i] = Entity.find_by_name("Shaft" .. (i - 1)) end
    show()
end

function update(entity, dt)
    nav.tick(SCENE)
    t = t + dt
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("G") then
        bounce = not bounce
        Lighting.set_global_illumination(bounce and 3 or 0)
        show()
    end
    -- The sun drifts: the light turns a little either way of where it was.
    local turn = math.sin(t * 0.12) * 0.1
    Transform.set_rotation(sun, turn)
    for _, e in ipairs(shafts) do Transform.set_rotation(e, SUN + turn) end
end
